// Generated by tools_rig from crate_templates/python
use std::{env, fs, path::PathBuf};

fn main() {
    // Write to generated/ in the crate directory (not OUT_DIR)
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let generated_dir = manifest_dir.join("generated");
    let baml_sdk_dir = generated_dir.join("baml_sdk");

    // Clean and recreate directories
    if generated_dir.exists() {
        fs::remove_dir_all(&generated_dir).unwrap();
    }
    fs::create_dir_all(&baml_sdk_dir).unwrap();

    // Pull the fixture from the `rig_fixtures` build-dep. The crate
    // replaces the deleted `baml_codegen_tests::fixtures::*` surface
    // with just the shapes each `python_*` rig crate needs.
    let fixture: baml_codegen_types::SymbolPool = rig_fixtures::fixture("full_type_coverage");

    // Generate Python code
    let output = baml_codegen_python::to_source_code(&fixture, &[]);

    // Write baml_sdk files
    for (path, content) in output {
        let file_path = baml_sdk_dir.join(&path);
        if let Some(parent) = file_path.parent() {
            fs::create_dir_all(parent).unwrap();
        }
        fs::write(&file_path, &content).unwrap();
    }

    // Symlink all files from customizable/ folder into generated/
    let customizable_dir = manifest_dir.join("customizable");
    if customizable_dir.exists() {
        for entry in fs::read_dir(&customizable_dir).unwrap() {
            let entry = entry.unwrap();
            let src = entry.path();
            let file_name = entry.file_name();
            let dst = generated_dir.join(&file_name);

            // Skip if not a file
            if !src.is_file() {
                continue;
            }

            // Remove existing symlink/file if present
            if dst.exists() || dst.symlink_metadata().is_ok() {
                let _ = fs::remove_file(&dst);
            }

            // Create symlink
            #[cfg(unix)]
            std::os::unix::fs::symlink(&src, &dst).unwrap_or_else(|_| {
                panic!(
                    "Failed to symlink {} from {}",
                    file_name.to_string_lossy(),
                    src.display()
                )
            });

            #[cfg(windows)]
            std::os::windows::fs::symlink_file(&src, &dst).unwrap_or_else(|_| {
                panic!(
                    "Failed to symlink {} from {}",
                    file_name.to_string_lossy(),
                    src.display()
                )
            });
        }
    }

    // Write a conftest.py that stubs `baml.baml_core` so the generated
    // `baml_sdk/__init__.py` (which does `from baml.baml_core import
    // BamlRuntime` at module load) can import without the real runtime
    // package installed. Matches the try/except-fallback behavior the
    // pre-phase-6 emitter baked in; see 10c-results §Phase 3 notes.
    let conftest_py = r#"# Generated by tools_rig from crate_templates/python
"""Stub `baml.baml_core` so baml_sdk imports work without the runtime."""
import sys
import types


def _install_baml_stub() -> None:
    if "baml.baml_core" in sys.modules:
        return

    baml = types.ModuleType("baml")
    baml_core = types.ModuleType("baml.baml_core")

    class BamlRuntime:  # noqa: D401
        @staticmethod
        def initialize_runtime(*_args, **_kwargs):
            return None

    def define_function(fqn, _kind, param_names):
        def factory(*_args, **_kwargs):
            raise RuntimeError(
                f"baml runtime not installed (called {fqn})"
            )
        factory.__name__ = fqn.rsplit(".", 1)[-1]
        factory.param_names = list(param_names)
        return factory

    baml_core.BamlRuntime = BamlRuntime
    baml_core.define_function = define_function
    baml.baml_core = baml_core

    sys.modules["baml"] = baml
    sys.modules["baml.baml_core"] = baml_core


_install_baml_stub()
"#;
    fs::write(generated_dir.join("conftest.py"), conftest_py).unwrap();

    // Write pyproject.toml
    let pyproject_toml = r#"[project]
name = "baml-test-full_type_coverage"
version = "0.1.0"
requires-python = ">=3.8"
dependencies = []

[tool.pytest.ini_options]
testpaths = ["."]
python_files = ["test_*.py"]
python_classes = ["Test*"]
python_functions = ["test_*"]
addopts = "-v"

[tool.ruff]
line-length = 120
# Exclude .pyi stub files from linting
extend-exclude = ["*.pyi"]

[tool.ruff.lint]
# Ignore lints that the generated tree legitimately trips:
# - F401: unused imports (leaf re-exports pull names in for typing)
# - F821: undefined name (forward refs resolve at runtime via PEP 563)
# - E402: module-level import not at top (09a Bootstrap puts
#   `BamlRuntime.initialize_runtime(...)` between imports by design)
ignore = ["F401", "F821", "E402"]
"#;
    fs::write(generated_dir.join("pyproject.toml"), pyproject_toml).unwrap();

    // Write test.sh script (Unix)
    let test_sh = r#"#!/usr/bin/env bash
# Generated by tools_rig from crate_templates/python
set -e

cd "$(dirname "$0")"

# Use a per-crate uv cache to avoid race conditions when tests run in parallel.
export UV_CACHE_DIR="$(pwd)/.uv-cache"

# Check if uv is available
if ! command -v uv &> /dev/null; then
    echo "Error: uv is not installed"
    echo "Install uv with: curl -LsSf https://astral.sh/uv/install.sh | sh"
    exit 1
fi

echo "==> Running Python syntax check..."
# Find all .py and .pyi files
python_files=$(find . -name "*.py" -o -name "*.pyi")
if [ -n "$python_files" ]; then
    echo "$python_files" | xargs uv run python -m py_compile
else
    echo "No Python files found to check"
fi

echo "==> Running ruff lint..."
uv run --with ruff ruff check --config pyproject.toml baml_sdk

echo "==> Running pytest..."
uv run --with pytest --with pydantic --with typing-extensions pytest -v

echo "==> All checks passed!"
"#;
    fs::write(generated_dir.join("test.sh"), test_sh).unwrap();

    // Make test.sh executable on Unix
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = fs::metadata(generated_dir.join("test.sh"))
            .unwrap()
            .permissions();
        perms.set_mode(0o755);
        fs::set_permissions(generated_dir.join("test.sh"), perms).unwrap();
    }

    // Write test.ps1 script (Windows)
    let test_ps1 = r#"# Generated by tools_rig from crate_templates/python
$ErrorActionPreference = "Stop"

Set-Location $PSScriptRoot

# Use a per-crate uv cache to avoid race conditions when tests run in parallel.
$env:UV_CACHE_DIR = Join-Path $PSScriptRoot ".uv-cache"

# Check if uv is available
if (-not (Get-Command uv -ErrorAction SilentlyContinue)) {
    Write-Error "Error: uv is not installed`nInstall uv with: irm https://astral.sh/uv/install.ps1 | iex"
    exit 1
}

Write-Host "==> Running Python syntax check..."
# Find all .py and .pyi files
$pythonFiles = Get-ChildItem -Recurse -Include *.py,*.pyi | ForEach-Object { $_.FullName }
if ($pythonFiles) {
    foreach ($file in $pythonFiles) {
        uv run python -m py_compile $file
    }
} else {
    Write-Host "No Python files found to check"
}

Write-Host "==> Running ruff lint..."
uv run --with ruff ruff check --config pyproject.toml baml_sdk

Write-Host "==> Running pytest..."
uv run --with pytest --with pydantic --with typing-extensions pytest -v

Write-Host "==> All checks passed!"
"#;
    fs::write(generated_dir.join("test.ps1"), test_ps1).unwrap();

    println!("cargo:rerun-if-changed=build.rs");

    // Watch all files in customizable/ folder
    if customizable_dir.exists() {
        for entry in fs::read_dir(&customizable_dir).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            if path.is_file() {
                println!("cargo:rerun-if-changed={}", path.display());
            }
        }
    }
}
